/**
 * ThinkingConfig
 *
 * Provider-neutral thinking/reasoning configuration.
 *
 * The runtime carries this as a neutral ``options["thinking"]`` payload and each
 * provider maps it to its own request shape (field-driven, no model lookup):
 *
 * - ``effort`` set -> adaptive thinking (Anthropic ``thinking={"type": "adaptive"}``
 * + ``output_config={"effort": ...}``; OpenAI ``reasoning={"effort": ...}``). This
 * is the path the current Claude and OpenAI reasoning models use.
 * - ``max_tokens`` set (and no ``effort``) -> legacy budgeted thinking (Anthropic
 * ``thinking={"type": "enabled", "budget_tokens": ...}``). Only the older Claude
 * models accept a token budget; OpenAI has no budget knob and ignores it.
 * - neither set, ``enabled=True`` -> adaptive thinking with provider defaults (on the
 * Chat Completions path this is a no-op: the model reasons by its own default).
 * - ``enabled=False`` is best-effort and provider-dependent: Anthropic disables
 * (``thinking={"type": "disabled"}``); OpenAI reasoning models cannot be disabled, so
 * it is a no-op (the model still reasons); the generic Chat Completions adapter also
 * no-ops (disabling isn't portable — pass a raw ``reasoning_effort`` via
 * ``provider_options`` to target a backend like Gemini that accepts ``"none"``).
 *
 * ``effort`` and ``max_tokens`` select mutually exclusive modes. Disabling thinking
 * cannot be combined with either enabled-mode control. Provider-specific support is
 * still validated by the provider; contradictory neutral controls fail here before a
 * provider request can be built.
 */
export type ThinkingConfig = {
    /**
     * Effort
     */
    effort?: 'low' | 'medium' | 'high' | null;
    /**
     * Enabled
     */
    enabled?: boolean;
    /**
     * Include In Transcript
     */
    include_in_transcript?: boolean;
    /**
     * Max Tokens
     */
    max_tokens?: number | null;
};

/**
 * ThinkingPart
 *
 * Model reasoning/thinking content from a single reasoning block.
 *
 * `text` may be empty (the provider returned the reasoning in an omitted/redacted
 * form). `provider_state` carries the opaque round-trip payload — the Anthropic
 * `signature` or `redacted_thinking` data, or an OpenAI encrypted reasoning blob —
 * needed to send the block back to the provider on a later turn. Built-in providers
 * tag opaque reasoning state with its provider family, protocol, and protocol version;
 * request adapters replay it only when all three match. Legacy untagged state remains
 * readable in the durable transcript but is not authoritative for opaque replay.
 */
export type ThinkingPart = {
    /**
     * Provider State
     */
    provider_state?: {
        [key: string]: unknown;
    } | null;
    /**
     * Text
     */
    text?: string;
    /**
     * Type
     */
    type?: 'thinking';
};

/**
 * TieredPricing
 *
 * Full pricing for one model: context-band tiers plus optional batch and
 * cache-write-duration rates.
 *
 * Only the context-band ``standard`` tiers feed the cost engine today. A tier-local
 * cache-write rate takes precedence over the model-wide
 * ``cache_write_5m_per_million`` fallback.
 * ``batch`` is carried for completeness and future use. Contextual pricing
 * applies ``cache_write_1h_per_million`` only to usage explicitly attributed
 * to a one-hour cache write.
 */
export type TieredPricing = {
    batch?: PriceTier | null;
    /**
     * Cache Write 1H Per Million
     */
    cache_write_1h_per_million?: number | string | null;
    /**
     * Cache Write 5M Per Million
     */
    cache_write_5m_per_million?: number | string | null;
    /**
     * Currency
     */
    currency?: string;
    /**
     * Standard
     */
    standard: Array<PriceTier>;
    /**
     * Web Search Per Thousand
     */
    web_search_per_thousand?: number | string | null;
};

